<template>
  <div class="rbac-page">
    <PageHead title="角色管理" desc="用户可绑定多个角色；有效授权取启用角色的权限并集。"><el-button type="primary" :disabled="!store.can('system:role:create')" @click="openRole()">新增角色</el-button></PageHead>
    <RbacModeNotice />
    <section class="panel"><div class="rbac-toolbar"><el-input v-model="search" clearable placeholder="搜索角色名称、编码" aria-label="搜索角色"/><el-select v-model="enabledFilter" clearable placeholder="全部状态" aria-label="角色状态"><el-option value="enabled" label="启用"/><el-option value="disabled" label="停用"/></el-select><span class="rbac-count">共 {{ filtered.length }} 个角色</span></div>
      <el-alert v-if="pageError" :title="pageError" type="error" :closable="false" class="rbac-error"/>
      <el-table :data="rows" class="rbac-table" empty-text="没有匹配角色"><el-table-column label="角色名称" min-width="180"><template #default="{row}"><strong :data-role-id="row.id">{{ row.name }}</strong><el-tag v-if="row.superAdmin" size="small" style="margin-left:8px">受保护</el-tag><div class="technical">{{ row.code }}</div></template></el-table-column><el-table-column label="状态" width="90"><template #default="{row}"><el-tag :type="row.enabled?'success':'info'">{{ row.enabled?'启用':'停用' }}</el-tag></template></el-table-column><el-table-column label="关联用户" width="105" align="right"><template #default="{row}"><el-button link type="primary" @click="showUsers(row)">{{ usersOf(row.id).length }}</el-button></template></el-table-column><el-table-column label="权限数量" width="105" align="right"><template #default="{row}">{{ row.permissionCodes.length }}</template></el-table-column><el-table-column prop="description" label="说明" min-width="220"/><el-table-column label="操作" width="210"><template #default="{row}"><div class="rbac-actions"><el-button link type="primary" :disabled="!store.can('system:role:update') || row.superAdmin" @click="openRole(row)">编辑</el-button><el-button link :disabled="!store.can('system:role:grant')" @click="openGrants(row)">配置权限</el-button><el-dropdown trigger="click"><el-button link>更多</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item v-if="row.superAdmin && store.isAdmin" @click="restoreSuperAdmin">恢复内置权限</el-dropdown-item><el-dropdown-item :disabled="!store.can('system:role:create')" @click="openRole(row,true)">复制角色</el-dropdown-item><el-dropdown-item :disabled="!store.can('system:role:update') || row.superAdmin" @click="toggleRole(row)">{{ row.enabled?'停用':'启用' }}</el-dropdown-item><el-dropdown-item @click="showUsers(row)">查看关联用户</el-dropdown-item><el-dropdown-item :disabled="!store.can('system:role:delete') || row.builtIn" @click="removeRole(row)">删除角色</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div></template></el-table-column></el-table><div class="rbac-pagination"><el-pagination v-model:current-page="page" :total="filtered.length" :page-size="15" layout="total, prev, pager, next"/></div>
    </section>
    <el-drawer v-model="editOpen" :title="editing ? '编辑角色' : '新增角色'" size="min(500px,95vw)" :before-close="closeEdit" :close-on-click-modal="false"><el-alert v-if="error" :title="error" type="error" :closable="false" class="rbac-error"/><el-form label-position="top" :disabled="busy"><el-form-item label="角色名称" required><el-input v-model="form.name" maxlength="80" aria-label="角色名称"/></el-form-item><el-form-item label="角色编码" required><el-input v-model="form.code" :disabled="!!editing" maxlength="80" aria-label="角色编码"/><p class="rbac-help">编码唯一且保存后保持稳定；修改显示名称不会改变授权身份。</p></el-form-item><el-form-item label="说明"><el-input v-model="form.description" type="textarea" :rows="3" maxlength="500"/></el-form-item><el-form-item label="状态"><el-switch v-model="form.enabled" :disabled="form.superAdmin" active-text="启用" inactive-text="停用"/></el-form-item><p class="rbac-help">{{ cloneSource ? `已复制「${cloneSource}」的显式权限点，保存后形成独立角色。` : '权限通过独立授权抽屉配置；新增角色默认没有权限。' }}</p></el-form><template #footer><el-button :disabled="busy" @click="closeEdit()">取消</el-button><el-button type="primary" :loading="busy" @click="saveRole">保存角色</el-button></template></el-drawer>
    <el-drawer v-model="grantOpen" :title="`配置权限 · ${grantRole?.name || ''}`" size="min(720px,96vw)" :before-close="closeGrant" :close-on-click-modal="false"><div class="rbac-drawer-body"><el-alert v-if="error" :title="error" type="error" :closable="false"/><p class="rbac-help">勾选分组只选择当前已有权限，不包含未来新增权限。页面访问与操作权限分别登记；依赖不会自动扩大授权。</p><el-alert v-if="grantRole?.superAdmin" title="内置超级管理员授权受保护，不能在此撤销。" type="info" :closable="false"/><div class="rbac-tree-toolbar"><el-input v-model="grantSearch" clearable placeholder="搜索模块、资源、权限码" aria-label="搜索授权权限"/><el-button @click="expandPermissions(true)">展开全部</el-button><el-button @click="expandPermissions(false)">收起全部</el-button><el-checkbox v-model="onlySelected">仅看已选</el-checkbox></div><div class="rbac-count">已选 {{ selectedCodes.length }} / {{ permissions.length }} 项</div><el-tree ref="grantTree" class="rbac-tree" :data="permissionTree" node-key="key" show-checkbox :props="{label:'label',children:'children',disabled:'disabled'}" :default-checked-keys="selectedCodes" default-expand-all :filter-node-method="filterPermission" @check="checked"><template #default="{data}"><span :data-permission-code="data.code" :data-permission-node="data.key">{{ data.label }}<small v-if="data.code" class="rbac-codes"> · {{ data.code }}</small><small v-if="data.dependencies?.length" class="rbac-codes">（依赖：{{ data.dependencies.join('、') }}）</small></span></template></el-tree><div class="rbac-diff" data-grant-diff>保存将新增 <strong>{{ added.length }}</strong> 项、撤销 <strong>{{ removed.length }}</strong> 项，影响 <strong>{{ usersOf(grantRole?.id || '').length }}</strong> 位关联用户。<p v-if="missingDependencies.length" class="rbac-help">尚缺依赖：{{ missingDependencies.join('、') }}。请明确勾选，系统不会自动授权。</p></div></div><template #footer><el-button :disabled="busy" @click="closeGrant()">取消</el-button><el-button type="primary" :disabled="!!grantRole?.superAdmin || !!missingDependencies.length" :loading="busy" @click="saveGrants">保存授权</el-button></template></el-drawer>
    <el-drawer v-model="usersOpen" :title="`关联用户 · ${referenceRole?.name || ''}`" size="min(460px,95vw)"><ul class="rbac-reference-list"><li v-for="user in usersOf(referenceRole?.id || '')" :key="user.id"><strong>{{ user.displayName }}</strong> <span class="rbac-codes">{{ user.username }}</span><el-tag size="small" :type="user.enabled?'success':'info'" style="margin-left:8px">{{ user.enabled?'启用':'停用' }}</el-tag></li></ul><el-empty v-if="!usersOf(referenceRole?.id || '').length" description="暂无关联用户"/></el-drawer>
  </div>
</template>
<script setup lang="ts">
import RbacModeNotice from '../components/rbac/RbacModeNotice.vue'
import { computed, nextTick, reactive, ref, watch } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { resourceLabel } from '../components/rbac/presentation'
import PageHead from '../components/PageHead.vue'
import { useRbacDraftGuard } from '../components/rbac/useRbacDraftGuard'
import '../components/rbac/admin.css'
import { uid, useCatalogStore } from '../stores/catalog'
import { isRetiredPermission } from '../domain/rbac'
import type { RbacRole } from '../domain/rbac'
const store=useCatalogStore(),search=ref(''),enabledFilter=ref(''),page=ref(1),pageError=ref(''),error=ref(''),busy=ref(false)
const editOpen=ref(false),grantOpen=ref(false),usersOpen=ref(false),editing=ref(''),initial=ref(''),cloneSource=ref(''),grantRole=ref<RbacRole>(),referenceRole=ref<RbacRole>()
const form=reactive<RbacRole>({id:'',name:'',code:'',description:'',enabled:true,permissionCodes:[]})
const roles=computed(()=>store.data.rbac?.roles || []),permissions=computed(()=>store.data.rbac?.permissions.filter(p=>!isRetiredPermission(p.code)) || [])
const filtered=computed(()=>roles.value.filter(r=>(!search.value||`${r.name} ${r.code}`.toLowerCase().includes(search.value.toLowerCase()))&&(!enabledFilter.value||(r.enabled?'enabled':'disabled')===enabledFilter.value)))
const rows=computed(()=>filtered.value.slice((page.value-1)*15,page.value*15));watch([search,enabledFilter],()=>page.value=1)
const selectedCodes=ref<string[]>([]),originalCodes=ref<string[]>([]),grantSearch=ref(''),onlySelected=ref(false),grantTree=ref<any>()
const added=computed(()=>selectedCodes.value.filter(c=>!originalCodes.value.includes(c))),removed=computed(()=>originalCodes.value.filter(c=>!selectedCodes.value.includes(c)))
const missingDependencies=computed(()=>[...new Set(permissions.value.filter(p=>selectedCodes.value.includes(p.code)).flatMap(p=>p.dependsOn || []).filter(code=>!selectedCodes.value.includes(code)))])
const dirty=computed(()=>editOpen.value&&JSON.stringify(form)!==initial.value || grantOpen.value&&(added.value.length>0||removed.value.length>0))
const {confirmDiscard}=useRbacDraftGuard(dirty)
function usersOf(id:string){return store.data.users.filter(u=>u.roleIds?.includes(id))}
function openRole(role?:RbacRole,clone=false){error.value='';editing.value=clone?'':role?.id||'';cloneSource.value=clone?role?.name||'':'';Object.assign(form,role?JSON.parse(JSON.stringify(role)):{id:'',name:'',code:'',description:'',enabled:true,permissionCodes:[],builtIn:false,superAdmin:false});if(clone){form.id='';form.code='';form.name=`${role?.name || ''} 副本`;form.builtIn=false;form.superAdmin=false}initial.value=JSON.stringify(form);editOpen.value=true}
async function closeEdit(done?:()=>void){if(busy.value)return;if(await confirmDiscard()){editOpen.value=false;done?.()}}
async function closeGrant(done?:()=>void){if(busy.value)return;if(await confirmDiscard()){grantOpen.value=false;done?.()}}
async function saveRole(){error.value='';if(!form.name.trim()||!form.code.trim()){error.value='请填写角色名称和唯一编码';return}busy.value=true;try{const result=await store.saveRbacRole({...JSON.parse(JSON.stringify(form)),id:editing.value||uid('role'),name:form.name.trim(),code:form.code.trim()});if(!result.ok){error.value=result.message||'保存失败';return}initial.value=JSON.stringify(form);editOpen.value=false;ElMessage.success('角色已保存')}finally{busy.value=false}}
async function toggleRole(role:RbacRole){const result=await store.saveRbacRole({...role,enabled:!role.enabled});if(!result.ok)pageError.value=result.message||'状态修改失败';else ElMessage.success('角色状态已更新')}
async function removeRole(role:RbacRole){if(usersOf(role.id).length){ElMessage.warning(`该角色仍关联 ${usersOf(role.id).length} 位用户，请先在用户管理调整绑定。`);return}try{await ElMessageBox.confirm(`删除角色「${role.name}」？`,'删除角色')}catch{return}const r=await store.removeRbacRole(role.id);if(!r.ok)pageError.value=r.message||'删除失败';else ElMessage.success('角色已删除')}
function showUsers(role:RbacRole){referenceRole.value=role;usersOpen.value=true}
interface PermissionTreeNode{key:string;label:string;code?:string;dependencies?:string[];searchText?:string;disabled?:boolean;children?:PermissionTreeNode[]}
const permissionTree=computed<PermissionTreeNode[]>(()=>{const modules=new Map<string,PermissionTreeNode>();for(const p of permissions.value){let module=modules.get(p.module);if(!module){module={key:`module:${p.module}`,label:p.module,children:[],disabled:!!grantRole.value?.superAdmin};modules.set(p.module,module)}let resource=module.children!.find(r=>r.key===`resource:${p.module}:${p.resource}`);if(!resource){resource={key:`resource:${p.module}:${p.resource}`,label:resourceLabel(p.resource),children:[],disabled:!!grantRole.value?.superAdmin};module.children!.push(resource)}resource.children!.push({key:p.code,code:p.code,label:`${p.name}${p.enabled?'':'（已停用）'}`,dependencies:p.dependsOn,searchText:`${p.module} ${p.resource} ${p.name} ${p.code}`,disabled:!!grantRole.value?.superAdmin||!p.enabled||!store.isAdmin&&!store.can(p.code)&&!selectedCodes.value.includes(p.code)})}return [...modules.values()]})
function openGrants(role:RbacRole){error.value='';grantRole.value=role;selectedCodes.value=[...role.permissionCodes];originalCodes.value=[...role.permissionCodes];grantSearch.value='';onlySelected.value=false;grantOpen.value=true;nextTick(()=>grantTree.value?.setCheckedKeys(selectedCodes.value))}
function checked(){selectedCodes.value=(grantTree.value?.getCheckedKeys(true)||[]).filter((k:unknown)=>typeof k==='string'&&permissions.value.some(p=>p.code===k));if(onlySelected.value)nextTick(()=>grantTree.value?.filter(grantSearch.value))}
function filterPermission(value:string,node:PermissionTreeNode):boolean{if(node.children)return node.children.some(child=>filterPermission(value,child));return (!onlySelected.value||selectedCodes.value.includes(node.code||''))&&(!value||(node.searchText||`${node.label} ${node.code}`).toLowerCase().includes(value.toLowerCase()))}
watch([grantSearch,onlySelected],()=>grantTree.value?.filter(grantSearch.value))
function expandPermissions(expand:boolean){for(const node of Object.values(grantTree.value?.store.nodesMap || {}) as {expanded:boolean}[])node.expanded=expand}
async function saveGrants(){busy.value=true;error.value='';try{const r=await store.grantRbacRole(grantRole.value!.id,[...selectedCodes.value]);if(!r.ok){error.value=r.message||'授权保存失败';return}originalCodes.value=[...selectedCodes.value];grantOpen.value=false;ElMessage.success('角色授权已保存')}finally{busy.value=false}}
async function restoreSuperAdmin() {
  if (!store.isAdmin || busy.value) return
  try { await ElMessageBox.confirm('恢复超级管理员的当前内置权限目录？不会改变用户身份、角色绑定或业务数据。', '恢复内置权限', { confirmButtonText: '确认恢复', cancelButtonText: '取消' }) } catch { return }
  busy.value = true; pageError.value = ''
  try { const result = await store.restoreSuperAdminAccess(); if (!result.ok) { pageError.value = result.message || '恢复失败，请重试。'; return }; ElMessage.success('已恢复内置权限') }
  catch (cause) { pageError.value = cause instanceof Error ? cause.message : '恢复失败，请重试。' }
  finally { busy.value = false }
}

</script>
